function gerarQueryEleitores(body) {
  let baseQuery = `SELECT * FROM public.gbp_eleitores WHERE`;
  let conditions = [];

  if (body.empresa_uid) {
    conditions.push(`empresa_uid = '${body.empresa_uid}'`);
  }

  if (body.cidade && body.cidade.length > 0) {
    if (body.cidade.length === 1) {
      conditions.push(`cidade = '${body.cidade[0]}'`);
    } else {
      conditions.push(`cidade = ANY(ARRAY[${body.cidade.map(c => `'${c}'`).join(', ')}])`);
    }
  }

  if (body.bairro && body.bairro.length > 0) {
    conditions.push(`bairro = ANY(ARRAY[${body.bairro.map(b => `'${b}'`).join(', ')}])`);
  }

  if (body.categoria && body.categoria.length > 0) {
    if (body.categoria.length === 1) {
      conditions.push(`categoria_uid = '${body.categoria[0]}'::uuid`);
    } else {
      conditions.push(`categoria_uid = ANY(ARRAY[${body.categoria.map(c => `'${c}'::uuid`).join(', ')}])`);
    }
  }

  if (body.genero) {
    conditions.push(`genero = '${body.genero}'`);
  }

  // Novo filtro: whatsapp não pode ser NULL nem string vazia
  conditions.push(`whatsapp IS NOT NULL AND whatsapp <> ''`);

  if (conditions.length > 0) {
    baseQuery += " " + conditions.join(" AND ");
  } else {
    baseQuery += " 1=1";
  }

  console.log("Query gerada:", baseQuery);
  return [{ query: baseQuery }];
}

